    const itemId = stableId("item", sha, filePath, sha256(content));
    files.push({
      id: stableId("file", sha, filePath),
      filePath,
      oldPath: null,
      status: "snapshot",
      beforeContent: null,
      afterContent: content,
      additions: 0,
      deletions: 0,
      language: languageForPath(filePath),
      size: content.length,
      items: [{
        id: itemId,
        kind: "file",
        filePath,
        oldPath: null,
        status: "snapshot",
        ordinal: 0,
        oldStart: null,
        oldLines: null,
        newStart: 1,
        newLines: source === "" ? 0 : source.split("\n").length,
        patch,
        contentHash: sha256(content),
      }],
    });
