export class DiffpanelStore {
  readonly home: string;
  readonly databasePath: string;
  readonly blobsPath: string;
  readonly runsPath: string;
  private readonly database: Database.Database;
  lastRecoveryReport: RecoveryReport | null = null;

  private constructor(home: string, databasePath: string, database: Database.Database) {
    this.home = home;
    this.databasePath = databasePath;
    this.blobsPath = join(home, "blobs");
    this.runsPath = join(home, "runs");
    this.database = database;
  }

  static async open(home = defaultDiffpanelHome(), options: OpenStoreOptions = {}): Promise<DiffpanelStore> {
    await mkdir(join(home, "blobs"), { recursive: true });
    await mkdir(join(home, "runs"), { recursive: true });
    const resolvedHome = await realpath(home);
    const databasePath = resolveDatabasePath(resolvedHome);
    const database = new Database(databasePath);
    try {
      database.pragma("busy_timeout = 30000");
      await withDatabaseQueue(databasePath, async () => {
        database.pragma("journal_mode = WAL");
        database.pragma("foreign_keys = ON");
        migrate(database);
      });
      const store = new DiffpanelStore(resolvedHome, databasePath, database);
      if (options.recover ?? true) store.lastRecoveryReport = await store.recover();
      return store;
    } catch (error) {
      database.close();
      throw error;
    }
  }

  close(): void {
    this.database.close();
  }

