import json
s=json.load(open('/tmp/diffpanel-pr1-snapshot-v14.json'))
for t in s['threads']:
 if t['isResolved']: continue
 print('\\nTHREAD',t['id'],t['path'])
 for c in t['comments']['nodes']:
  print(' ',c['url'],'outdated='+str(c['outdated']),c['body'].replace('\\n',' ')[:1100])
print('\\nANNOTATIONS')
for r in s['check_runs']:
 if r.get('annotations'):
  print('RUN',r['name'],r['details_url'],r['output'])
  for a in r['annotations']:
   print(a['annotation_level'],a['path'],a['start_line'],a['message'].replace('\\n',' ')[:1500])
print('\\nREVIEWS')
for r in s['pre']['reviews']:
 b=r.get('body') or ''
 if b.strip(): print(r.get('author',{}).get('login'),r.get('submittedAt'),r.get('state'),b.replace('\\n',' ')[:1000])
print('\\nISSUE COMMENTS')
for c in s['pre']['comments']:
 print(c.get('author',{}).get('login'),c.get('createdAt'),(c.get('body') or '').replace('\\n',' ')[:1000])
PY`;const r=await tools.exec_command({cmd,max_output_tokens:20000});text(r.output)

