    `);
    insertRun.run(
      runId,
      captured.repositoryId,
      captured.repositoryRoot,
      captured.repositoryName,
      JSON.stringify(captured.scope),
      snapshotHash,
      createdAt,
      files.length,
      itemCount,
      manifestPath,
