async function captureChangedFileWithSizeSkip(
  repositoryRoot: string,
  scope: ChangedScope,
  changedPath: ChangedPath,
  limits: CaptureLimits,
  processOptions: ProcessOptions,
): Promise<CapturedFile | { reason: string }> {
  try {
    return await captureChangedFile(repositoryRoot, scope, changedPath, limits, processOptions);
  } catch (error) {
    if (error instanceof GitObjectTooLargeError) return { reason: `file exceeds ${limits.maxFileBytes} bytes` };
    throw error;
  }
}

function captureFingerprint(captured: Awaited<ReturnType<typeof captureChangedScope>>): string {
  return sha256(JSON.stringify({
    changedPaths: captured.changedPaths,
    skipped: captured.skipped,
    files: captured.files.map((file) => ({
      ...file,
      beforeContent: file.beforeContent?.toString("base64") ?? null,
      afterContent: file.afterContent?.toString("base64") ?? null,
    })),
  }));
}

export function parseNameStatus(buffer: Buffer): ChangedPath[] {
  const fields = splitNull(buffer);
  const records: ChangedPath[] = [];
  let index = 0;
  while (index < fields.length) {
    const statusCode = fields[index++];
    if (!statusCode) continue;
    const code = statusCode[0];
    if (code === "R" || code === "C") {
      const oldPath = fields[index++];
      const filePath = fields[index++];
      if (!oldPath || !filePath) throw new Error("Malformed renamed/copied path record from Git.");
      assertSafeRepositoryPath(oldPath);
      assertSafeRepositoryPath(filePath);
      records.push({ status: code === "R" ? "renamed" : "copied", oldPath, filePath });
      continue;
    }
    const filePath = fields[index++];
    if (!filePath) throw new Error("Malformed changed path record from Git.");
    assertSafeRepositoryPath(filePath);
    records.push({ status: mapStatus(code), oldPath: null, filePath });
  }
  return records;
}

function parseRawGitlinks(buffer: Buffer): Set<string> {
  const fields = splitNull(buffer);
  const gitlinks = new Set<string>();
  let index = 0;
  while (index < fields.length) {
    const header = fields[index++];
    const match = header?.match(/^:(\d{6}) (\d{6}) \S+ \S+ ([A-Z])\d*$/);
    if (!match) throw new Error("Malformed raw path record from Git.");
    const oldPath = fields[index++];
    const filePath = match[3] === "R" || match[3] === "C" ? fields[index++] : oldPath;
    if (!oldPath || !filePath) throw new Error("Malformed raw path record from Git.");
    assertSafeRepositoryPath(oldPath);
    assertSafeRepositoryPath(filePath);
    if (match[1] === "160000" || match[2] === "160000") {
      gitlinks.add(oldPath);
      gitlinks.add(filePath);
    }
  }
  return gitlinks;
}

function splitNull(buffer: Buffer): string[] {
  return buffer.toString("utf8").split("\0").filter(Boolean);
}

function mapStatus(code: string | undefined): CapturedFile["status"] {
  if (code === "A") return "added";
  if (code === "M" || code === "T") return "modified";
  if (code === "D") return "deleted";
  if (code === "U") return "unmerged";
  return "unknown";
}

async function captureChangedFile(
  repositoryRoot: string,
  scope: ChangedScope,
  changedPath: ChangedPath,
  limits: CaptureLimits,
  processOptions: ProcessOptions,
): Promise<CapturedFile | { reason: string }> {
  const beforePath = changedPath.oldPath ?? changedPath.filePath;
  const beforeContent = await readBeforeContent(repositoryRoot, scope, beforePath, changedPath.status, limits.maxFileBytes, processOptions);
  let afterContent: Buffer | null;
  try {
    afterContent = await readAfterContent(
      repositoryRoot,
      scope,
      changedPath.filePath,
      changedPath.status,
      limits.maxFileBytes,
      processOptions,
    );
  } catch (error) {
    if (error instanceof WorktreeFileTooLargeError) return { reason: `file exceeds ${limits.maxFileBytes} bytes` };
    throw error;
  }
  const largest = Math.max(beforeContent?.length ?? 0, afterContent?.length ?? 0);
  if (largest > limits.maxFileBytes) return { reason: `file exceeds ${limits.maxFileBytes} bytes` };
  if (isBinary(beforeContent) || isBinary(afterContent)) return { reason: "binary file" };

  const patch = await readPatch(repositoryRoot, scope, changedPath, beforeContent, afterContent, processOptions);
  const items = parseHunks(patch, changedPath);
  // Git can report a real path/mode change without producing a textual hunk.
  // Keep its metadata as review evidence, including an empty file rename.
  if (items.length === 0) {
    const contentHash = sha256(patch || JSON.stringify(changedPath));
    items.push({
      id: stableId("item", changedPath.filePath, changedPath.oldPath, contentHash),
      kind: "file",
      ...changedPath,
      ordinal: 0,
      oldStart: null, oldLines: null, newStart: null, newLines: null,
      patch,
      contentHash,
    });
  }
  const additions = items.reduce((total, item) => total + countPatchLines(item.patch, "+"), 0);
  const deletions = items.reduce((total, item) => total + countPatchLines(item.patch, "-"), 0);
  return {
    id: stableId("file", changedPath.filePath, changedPath.oldPath, changedPath.status),
    ...changedPath,
    beforeContent,
    afterContent,
    additions,
    deletions,
    language: languageForPath(changedPath.filePath),
    size: afterContent?.length ?? beforeContent?.length ?? 0,
    items,
  };
}

async function readBeforeContent(
  repositoryRoot: string,
  scope: ChangedScope,
  filePath: string,
  status: CapturedFile["status"],
  maxFileBytes: number,
  processOptions: ProcessOptions,
): Promise<Buffer | null> {
  if (status === "added") return null;
  return await readGitObject(repositoryRoot, scope.baseSha, filePath, false, maxFileBytes, processOptions);
}

async function readAfterContent(
  repositoryRoot: string,
  scope: ChangedScope,
  filePath: string,
  status: CapturedFile["status"],
  maxFileBytes: number,
  processOptions: ProcessOptions,
): Promise<Buffer | null> {
  if (status === "deleted") return null;
  if (scope.type === "worktree") return await readWorktreeFile(repositoryRoot, filePath, maxFileBytes);
  if (scope.type === "staged") {
    return scope.indexSha
      ? await readGitObject(repositoryRoot, scope.indexSha, filePath, false, maxFileBytes, processOptions)
      : await readGitObject(repositoryRoot, "", filePath, true, maxFileBytes, processOptions);
  }
  if (scope.type === "range") return await readGitObject(repositoryRoot, scope.compareSha, filePath, false, maxFileBytes, processOptions);
  return null;
}

async function readGitObject(
  repositoryRoot: string,
  ref: string,
  filePath: string,
  index: boolean,
  maxFileBytes: number,
  processOptions: ProcessOptions,
): Promise<Buffer | null> {
  const spec = index ? `:${filePath}` : `${ref}:${filePath}`;
  const sizeResult = await runProcess("git", ["cat-file", "-s", spec], repositoryRoot, {
    ...processOptions,
    acceptedExitCodes: [0, 128],
  });
  if (sizeResult.exitCode !== 0) {
    if (!await gitPathExists(repositoryRoot, ref, filePath, index, processOptions)) return null;
    throw new Error(`git cat-file -s ${spec} failed (${sizeResult.exitCode}): ${sizeResult.stderr.toString("utf8").trim()}`);
  }
  const size = Number(sizeResult.stdout.toString("utf8").trim());
  if (!Number.isSafeInteger(size) || size < 0) throw new Error(`Invalid Git object size for ${spec}.`);
  if (size > maxFileBytes) throw new GitObjectTooLargeError();
  const result = await runProcess("git", ["show", spec], repositoryRoot, {
    ...processOptions,
    acceptedExitCodes: [0, 128],
  });
  if (result.exitCode === 0) return result.stdout;
  if (!await gitPathExists(repositoryRoot, ref, filePath, index, processOptions)) return null;
  throw new Error(`git show ${spec} failed (${result.exitCode}): ${result.stderr.toString("utf8").trim()}`);
}

async function gitPathExists(
  repositoryRoot: string,
  ref: string,
  filePath: string,
  index: boolean,
  processOptions: ProcessOptions,
): Promise<boolean> {
  const records = splitNull(await gitBuffer(repositoryRoot, index
    ? ["ls-files", "--stage", "-z", "--", filePath]
    : ["ls-tree", "-z", ref, "--", filePath], processOptions));
  return records.some((record) => {
    const tab = record.indexOf("\t");
    if (tab < 0 || record.slice(tab + 1) !== filePath) return false;
    return !index || /\s0$/u.test(record.slice(0, tab));
  });
}

async function readPatch(
  repositoryRoot: string,
  scope: ChangedScope,
  changedPath: ChangedPath,
  beforeContent: Buffer | null,
  afterContent: Buffer | null,
  processOptions: ProcessOptions,
): Promise<string> {
  if (changedPath.status === "added" && beforeContent === null && afterContent !== null) {
    return syntheticAdditionPatch(afterContent.toString("utf8"));
  }
  const args = ["diff", "--no-ext-diff", "--no-color", "--unified=3"];
  if (scope.type === "staged") {
    if (scope.indexSha) args.push(scope.baseSha, scope.indexSha);
    else args.push("--cached", scope.baseSha);
  }
  else if (scope.type === "worktree") args.push(scope.baseSha);
  else if (scope.type === "range") args.push(scope.baseSha, scope.compareSha);
  const paths = changedPath.oldPath
    ? [changedPath.oldPath, changedPath.filePath]
    : [changedPath.filePath];
  args.push("--", ...paths);
  return (await gitBuffer(repositoryRoot, args, processOptions)).toString("utf8");
}

function syntheticAdditionPatch(content: string): string {
  const sourceLines = content === "" ? [] : content.replace(/\n$/, "").split("\n");
  const count = sourceLines.length;
  return [`@@ -0,0 +1,${count} @@`, ...sourceLines.map((line) => `+${line}`)].join("\n");
}

export function parseHunks(patch: string, changedPath: ChangedPath): ReviewItem[] {
  const lines = patch.split("\n");
  const hunks: ReviewItem[] = [];
  let current: string[] | null = null;
  let coordinates: RegExpMatchArray | null = null;

  const flush = () => {
    if (!current || !coordinates) return;
    const oldStart = Number(coordinates[1]);
    const oldLines = Number(coordinates[2] ?? 1);
    const newStart = Number(coordinates[3]);
    const newLines = Number(coordinates[4] ?? 1);
    const hunkPatch = current.join("\n");
    const ordinal = hunks.length;
    hunks.push({
      id: stableId("item", changedPath.filePath, oldStart, newStart, sha256(hunkPatch)),
      kind: "hunk",
      filePath: changedPath.filePath,
      oldPath: changedPath.oldPath,
      status: changedPath.status,
      ordinal,
      oldStart,
      oldLines,
      newStart,
      newLines,
      patch: hunkPatch,
      contentHash: sha256(hunkPatch),
    });
  };

  for (const line of lines) {
    const match = line.match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);
    if (match) {
      flush();
      coordinates = match;
      current = [line];
    } else if (current) {
      current.push(line);
    }
  }
  flush();
  return hunks;
}

function countPatchLines(patch: string, prefix: "+" | "-"): number {
  return patch.split("\n").filter((line) => line.startsWith(prefix) && !line.startsWith(`${prefix}${prefix}${prefix}`)).length;
}

function isBinary(content: Buffer | null): boolean {
  return content?.includes(0) ?? false;
}

function languageForPath(filePath: string): string | null {
  const extension = extname(filePath).slice(1).toLowerCase();
  const languages: Record<string, string> = {
    c: "c", cc: "cpp", cpp: "cpp", cs: "csharp", css: "css", go: "go", html: "html",
    java: "java", js: "javascript", json: "json", jsx: "javascriptreact", kt: "kotlin",
    md: "markdown", php: "php", py: "python", rb: "ruby", rs: "rust", sh: "shellscript",
    sql: "sql", svelte: "svelte", swift: "swift", ts: "typescript", tsx: "typescriptreact",
    vue: "vue", yaml: "yaml", yml: "yaml",
  };
  return languages[extension] ?? (extension || null);
}

async function captureRepositorySnapshot(
  repositoryRoot: string,
  ref: string,
  maxFiles: number,
  limits: CaptureLimits,
  options: CaptureOptions,
  processOptions: ProcessOptions,
): Promise<CapturedReview> {
  validateRef(ref);
  const sha = await gitText(repositoryRoot, ["rev-parse", "--verify", ref], processOptions);
  const entries = splitNull(await gitBuffer(repositoryRoot, ["ls-tree", "-r", "-z", sha], processOptions)).map((record) => {
    const separator = record.indexOf("\t");
    if (separator < 0) throw new Error("Malformed tree entry from Git.");
    const [mode, type] = record.slice(0, separator).split(" ");
    const filePath = record.slice(separator + 1);
    if (!mode || !type) throw new Error("Malformed tree entry from Git.");
    assertSafeRepositoryPath(filePath);
    return { mode, type, filePath };

import { appendFile, readFile } from 'node:fs/promises';
import path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';
import { npmTagForVersion } from './release-version.mjs';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const repoRoot = path.resolve(__dirname, '..');
const releasePackagesPath = path.join(repoRoot, 'release-packages.json');
const tagPattern = /^(?<slug>[a-z0-9][a-z0-9-]*)-v(?<version>\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)$/;

function fail(message) {
  console.error(message);
  process.exit(1);
}

async function loadReleaseTargets() {
  const raw = await readFile(releasePackagesPath, 'utf8');
  const releasePackages = JSON.parse(raw);

  if (!Array.isArray(releasePackages)) {
    fail(`Expected ${path.relative(repoRoot, releasePackagesPath)} to contain an array`);
  }

  const targets = [];
  const slugs = new Set();

  for (const entry of releasePackages) {
    if (!entry?.slug || !entry?.path || !entry?.name) {
      fail(`Invalid release target entry in ${path.relative(repoRoot, releasePackagesPath)}: ${JSON.stringify(entry)}`);
    }

    if (slugs.has(entry.slug)) {
      fail(`Duplicate release target slug: ${entry.slug}`);
    }

    const packagePath = path.resolve(repoRoot, entry.path);
    const relativePackagePath = path.relative(repoRoot, packagePath);

    if (relativePackagePath.startsWith('..') || path.isAbsolute(relativePackagePath)) {
      fail(`Release target ${entry.slug} resolves outside the repository: ${entry.path}`);
    }

    slugs.add(entry.slug);
    targets.push({
      slug: entry.slug,
      name: entry.name,
      path: relativePackagePath,
    });
  }

  return targets;
}

async function writeOutputs(outputs) {
  if (!process.env.GITHUB_OUTPUT) {
    return;
  }

  const lines = Object.entries(outputs).map(([key, value]) => `${key}=${value}`);
  await appendFile(process.env.GITHUB_OUTPUT, `${lines.join('\n')}\n`);
}

const tag = process.argv[2] ?? process.env.GITHUB_REF_NAME;

if (!tag) {
  fail('Expected a release tag argument or GITHUB_REF_NAME');
}

const match = tag.match(tagPattern);

if (!match?.groups) {
  fail(`Unsupported tag format: ${tag}. Expected <package-slug>-v<version>.`);
}

const { slug, version } = match.groups;
const npmTag = npmTagForVersion(version);
const releaseTargets = await loadReleaseTargets();
const target = releaseTargets.find((candidate) => candidate.slug === slug);

if (!target) {
  const supportedSlugs = releaseTargets.map((candidate) => candidate.slug).join(', ');
  fail(`No publishable workspace found for slug "${slug}". Supported slugs: ${supportedSlugs}`);
}

const packageJsonFile = path.join(repoRoot, target.path, 'package.json');
const packageJson = JSON.parse(await readFile(packageJsonFile, 'utf8'));

if (packageJson.name !== target.name) {
  fail(
    `Release target ${target.slug} expected ${target.name} at ${target.path}/package.json, found ${packageJson.name ?? 'undefined'}`,
  );
}

if (packageJson.private) {
  fail(`Release target ${target.slug} is private in ${target.path}/package.json`);
}

if (packageJson.version !== version) {
  fail(`Tag version ${version} does not match ${target.name}@${packageJson.version} in ${target.path}/package.json`);
}

await writeOutputs({
  pkg_slug: target.slug,
  pkg_name: target.name,
  pkg_version: packageJson.version,
  pkg_path: target.path,
  npm_tag: npmTag,
});

console.log(
  JSON.stringify(
    {
      tag,
      slug: target.slug,
      name: target.name,
      version: packageJson.version,
      path: target.path,
      npmTag,
    },
    null,
    2,
  ),
);

